		parameter
		COUNTER_WIDTH = 25,
		CEILING_WIDTH = 4
	)(
		input  wire                    clk_in,
		input  wire[CEILING_WIDTH-1:0] ceiling_in,
		output reg                     tick_out
	);

	localparam TOP_BIT = 2**CEILING_WIDTH - 1;
	function[TOP_BIT:0] reverse(input[COUNTER_WIDTH:0] fwd);
		integer i;
		for ( i = 0; i <= TOP_BIT; i = i + 1 )
			reverse[i] = fwd[COUNTER_WIDTH-i];
