	always @(posedge clk_in)
		count <= count_next;

	assign revCount = reverse(count);

	always @*
	begin
		if ( revCount[ceiling_in] == 1'b0 )
			begin
				count_next = count + 1'b1;
				tick_out = 1'b0;
			end
		else
			begin
				count_next = 0;
				tick_out = 1'b1;
			end
	end
endmodule

